const $=s=>document.querySelector(s);
const standalone=['/','/index.html'].includes(location.pathname);
const [config,order]=await Promise.all([fetch('./specimens.json').then(r=>r.json()),fetch('./css-order.json').then(r=>r.json())]);
if(!standalone){$('#current-tab').hidden=true;document.querySelector('.mast a').href='/docs/design/mobile-visual-standard.md';}
const fixtures=new Map(config.fixtures.map(f=>[f.name,f]));
const groups=[['页面与导航',[['chat-blue-light','聊天页面'],['spaces','空间列表 · 短'],['spaces-long','空间列表 · 长'],['settings','设置'],['verify','身份验证'],['verify-keyboard','验证 · 键盘示意'],['reader','文档阅读'],['call','通话'],['privacy','隐私遮蔽']]],['弹窗与表单',[['invite','邀请加入'],['avatar','头像来源'],['password','操作密码'],['restore','历史恢复'],['joint','联合恢复'],['backup-privacy','备份隐私'],['message-info','消息信息'],['media','图片详情'],['confirm','危险确认'],['nameform','编辑名称'],['summary','复杂摘要'],['release','更新说明']]],['组件与消息',[['inputs','输入与错误'],['controls','选择与开关'],['buttons','按钮状态矩阵'],['feedback','提示与反馈'],['loading','加载与空状态'],['menu','长按动作菜单'],['bubble-media','图片与视频'],['bubble-album','相册与表情'],['bubble-file-voice','文件与语音'],['gradient-a','可见范围渐变 · 位置A'],['gradient-b','可见范围渐变 · 位置B']]],['动效体验',[['motion-menu','长按整组移动'],['motion-page','页面进入与退出']]],['18种媒体状态',config.fixtures.filter(f=>f.name.startsWith('state-')).map(f=>[f.name,f.html.match(/<h2>.*?<\/span>(.*?)<\/h2>/)?.[1]||f.name])]];
const labels=new Map(groups.flatMap(g=>g[1]));
const stateList=groups.at(-1)[1];let selected='chat-blue-light';let ready=false;let sequenceTimer;let captures=[];
const specifics={
 'invite':['统一半屏节奏','柄区44；横20；标题→说明12；内容组24。','按钮后的提示左对齐，12／1.6／400，距按钮12。','邀请内容的剩余高度只进入内容伸缩区。'],
 'restore':['单行、多行共用相邻关系','标题→说明12；说明→输入24。','输入→错误12；错误→操作24；操作44。','取消使用业务取消入口，不叠加X。'],
 'password':['安全验证的同一节奏','与历史恢复使用同一套12／24关系。','填充型输入，无触控聚焦描边。','取消立即清理，不等待动画。'],
 'media':['详情分隔保持轻','只读行最小40，最后一行无分隔。','分隔为line的45%alpha，左右对齐20内容边。','半屏柄区44、标题到内容24。'],
 'controls':['整行选择与不同密度','单选尾勾；多选使用柔和填充标记。','紧凑／常规／宽松Tab视觉高28／32／40。','所有操作热区至少44，不挤占相邻目标。'],
 'spaces':['选择与新建入口','当前项仅背景选择，不重复画右侧勾。','新建入口固定在底部，长短列表位置一致。','列表滚动时末行不被底部操作挡住。'],
 'spaces-long':['长列表的可达性','列表单独滚动，底部新建入口保持可达。','末项具有底部操作与安全区的避让。','返回保留原来的列表位置。'],
 'reader':['安静的阅读操作','目录、轻页码入口和阅读设置各有44热区。','不常驻粗重左右翻页器。','PDF、EPUB与纯文本仍沿用各自导航方式。'],
 'verify-keyboard':['短视口与键盘','输入、错误与主操作在可见区可达。','网页操作栏、浏览器原生输入工具栏颜色连续。','图中键盘是几何示意，不能代表iPhone实测。'],
 'motion-menu':['长按整组移动','气泡、回应条、动作卡片放在同一父组，240ms同速移动。','打开和归位连续；途中再次操作，从当前位置与速度反向。','菜单没有默认选中；回应与动作仅作本地视觉示例。'],
 'motion-page':['层级进入与返回','目标页W→0，来源页0→−0.18W；280ms。','点击可前进、返回或途中反向；同级切换另用180ms淡化。','隐私锁定0ms；键盘变化不触发页面滑入。'],
 'menu':['长按整组移动','气泡、回应条、动作卡片共用父组轨迹。','240ms连续打开和归位，组内相对位置恒定。','回复、复制没有默认选中；隐私退出立即清理。'],
};
function nav(){const term=$('#search').value.trim();$('#catalog').replaceChildren();for(const [heading,list] of groups){const filtered=list.filter(([id,label])=>(id+label).toLowerCase().includes(term.toLowerCase()));if(!filtered.length)continue;const h=document.createElement('div');h.className='nav-group';h.textContent=heading;$('#catalog').append(h);for(const [id,label] of filtered){const b=document.createElement('button');b.textContent=label;b.dataset.id=id;b.setAttribute('aria-current',selected===id?'page':'false');b.onclick=()=>select(id);$('#catalog').append(b)}}}
function tell(type,more={}){$('#surface').contentWindow?.postMessage({type,...more},location.origin)}
function select(id,fromFrame=false){if(!fixtures.has(id))return;const previous=selected;selected=id;nav();const f=fixtures.get(id);$('#title').textContent=labels.get(id)||id;const media=id.startsWith('state-');$('#media-controls').hidden=!media;$('#motion-controls').hidden=!id.startsWith('motion-');$('#description').textContent=media?'切换状态或播放发送流程，观察固定媒体外框与32px胶囊的连续变化。':'可点击返回、取消和体验表单反馈。所有内容均为合成样例。';
const items=media?['同一胶囊的连续切换','所有右下胶囊视觉高度32，操作仍有44热区。','上传失败去掉角落X，文字移除放在媒体动作面板。','媒体框稳定；文字180ms淡化、外壳240ms，尺寸补全280ms。']:(specifics[id]||['保持内容优先','沿用P1的不透明柔和底色、系统字族和紧凑比例。','控制、间距、状态遵守同一角色，不按页面随意变化。','点击返回或取消可体验相邻流程；模拟不执行真实业务。']);$('#note-title').textContent=items[0];$('#checks').replaceChildren(...items.slice(1).map(t=>{const li=document.createElement('li');li.textContent=t;return li}));
$('#state-select').value=id;
if(media&&previous.startsWith('state-')&&ready){tell('media-state',{fixture:f});return;}
ready=false;render(f);}
function render(f){const width=Number($('#size').value);const actualWidth=f.width>500?f.width:width;$('#surface').style.width=actualWidth+'px';const height=Number($('#height').value);$('#surface').style.height=height+'px';$('#viewport-value').textContent=`${actualWidth} × ${height} CSS px`;const links=order.map(x=>`<link rel="stylesheet" href="${standalone?'/product-css/':'/'}${x}">`).join('');const theme=$('#theme').value,scheme=$('#scheme').value;
$('#surface').srcdoc=`<!doctype html><html lang="zh-CN" data-theme="${theme}" data-color-scheme="${scheme}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta http-equiv="Content-Security-Policy" content="connect-src 'none'; form-action 'none'"><title>${labels.get(f.name)||f.name}</title>${links}<style>${config.common}\n${f.css}\nhtml,body{min-height:100%;margin:0}#app{min-height:100vh}#app .v13-state-card{padding-top:44px}button,input,textarea,select{touch-action:manipulation}.review-action-panel{position:fixed;inset:auto 0 0;background:var(--surface-raised);padding:20px;border-radius:18px 18px 0 0;box-shadow:0 -100vh 0 100vh #18231c59;z-index:500}.review-action-panel button{display:block;width:100%;height:48px;margin:0;border:0;background:none;color:var(--ink);font-size:14px}.review-action-panel button[data-remove]{color:var(--danger)}.review-toast{position:fixed;top:64px;left:20px;right:20px;background:var(--surface-raised);color:var(--ink);border-radius:12px;padding:12px;font-size:13px;z-index:900}.review-caption{padding:20px;font-size:12px;color:var(--ink-muted)}</style><body class="app-mode"><div id="app" data-review-name="${f.name}" data-control-feedback="false">${f.html}</div><script src="${new URL("./surface.js",location.href).href}"><\/script></body></html>`;}
function tab(which){for(const t of ['target','current','flow']){$('#'+t+'-tab').setAttribute('aria-selected',String(t===which));$('#'+t+'-view').hidden=t!==which}$('#reset').hidden=which!=='target';$('#eyebrow').textContent=which==='current'?'实际代码 · 截图证据':which==='flow'?'审阅 R1 · 正式产品待实施':'规范目标 · 独立原型';if(which==='current')refreshCaptures()}
async function refreshCaptures(){captures=await fetch('/evidence.json').then(r=>r.json());const current=$('#capture-select').value;$('#capture-select').replaceChildren(...captures.filter(c=>{const kind=$('#capture-group').value;return kind==='all'||kind==='dark'&&c.name.includes('dark')||kind==='compact'&&/320|small|landscape|520|450/.test(c.name)||kind==='mobile'&&!/dark|text200|320|768|1024|1280|1440|landscape|small|520|450|844/.test(c.name);}).map(c=>{const o=document.createElement('option');o.value=c.url;o.textContent=c.name;return o}));if([...$('#capture-select').options].some(c=>c.value===current))$('#capture-select').value=current;showCapture();}
function showCapture(){const c=captures.find(x=>x.url===$('#capture-select').value)||captures.find(c=>c.url===$('#capture-select').options[0]?.value);if(c){$('#capture').src=c.url;$('#capture').alt=c.name;$('#announcement').textContent=''}else $('#announcement').textContent='页面采集中，稍后更新列表。'}
for(const t of ['target','current','flow'])$('#'+t+'-tab').onclick=()=>tab(t);
for(const id of ['size','height','theme','scheme'])$('#'+id).onchange=()=>{ready=false;render(fixtures.get(selected))};$('#search').oninput=nav;$('#reset').onclick=()=>{clearTimeout(sequenceTimer);render(fixtures.get(selected))};$('#state-select').onchange=e=>select(e.target.value);$('#capture-select').onchange=showCapture;$('#capture-group').onchange=refreshCaptures;$('#refresh-captures').onclick=refreshCaptures;
$('#geometry').onclick=()=>tell('geometry');$('#motion-toggle').onclick=()=>tell('demo-motion');$('#reduce').onchange=e=>tell('reduce',{value:e.target.checked});
$('#sequence').onclick=()=>{clearTimeout(sequenceTimer);let i=0;const list=['state-P01','state-P02','state-P03','state-P04','state-P05','state-P06'];const next=()=>{select(list[i++]);if(i<list.length)sequenceTimer=setTimeout(next,1250)};next()};
for(const [id,label] of stateList){const o=document.createElement('option');o.value=id;o.textContent=id.slice(6)+' · '+label;$('#state-select').append(o)}
window.addEventListener('message',e=>{if(e.source!==$('#surface').contentWindow||e.origin!==location.origin)return;const d=e.data;if(d.type==='ready'){ready=true;tell('reduce',{value:$('#reduce').checked})}if(d.type==='navigate'){clearTimeout(sequenceTimer);select(d.id,true)}if(d.type==='notice')$('#announcement').textContent=d.text;});
select(new URLSearchParams(location.search).get('surface')||'chat-blue-light');
